args=[sys.executable,str(root.parent/'build.py'),str(root/'app.c'),'--opt','speed','--math','--include',str(root/'compat'),'--include',str(root/'core'),'--extra-source',str(root.parent/'common/runtime.c'),'--extra-source',str(root.parent/'common/game_runtime.c'),'--extra-source',str(root.parent/'common/math.c')]
